<template>
  <article v-if="note" class="knowledge-reader">
    <header class="reader-top">
      <div class="breadcrumbs"><button type="button" @click="$emit('show-overview')">Библиотека</button><UiIcon name="right"/><span>{{ note.section }}</span></div>
      <div class="reader-actions"><UiIconButton icon="star" :label="note.pinned?'Убрать из избранного':'В избранное'" :variant="note.pinned?'accent':'neutral'" @click="$emit('toggle-pinned')"/><UiIconButton icon="edit" label="Редактировать" @click="$emit('edit')"/><UiIconButton icon="trash" label="Удалить" variant="danger" @click="$emit('delete')"/></div>
    </header>
    <div class="reading-progress"><i :style="{width:`${scrollProgress}%`}"/></div>
    <div ref="scrollElement" class="reader-layout" @scroll.passive="updateScrollProgress">
      <div class="reader-document">
        <div class="reader-kicker"><span>{{ note.section }}</span><b>{{ readingMinutes }} мин чтения</b></div>
        <h1>{{ note.title }}</h1>
        <div class="reader-meta"><span>Обновлено {{ formatDate(note.updatedAt) }}</span><button v-for="tag in note.tags||[]" :key="tag" type="button" @click="$emit('search-tag',tag)">#{{ tag }}</button></div>
        <nav v-if="headings.length" class="reader-outline" aria-label="Оглавление материала"><span>В материале</span><button v-for="heading in headings" :key="heading.index" type="button" @click="scrollToHeading(heading.index)">{{ heading.text }}</button></nav>
        <div class="reader-content"><template v-for="(block,index) in contentBlocks" :key="index"><h2 v-if="block.type==='heading'" :data-heading-index="index">{{ block.text }}</h2><blockquote v-else-if="block.type==='quote'">{{ block.text }}</blockquote><ul v-else-if="block.type==='list'"><li v-for="item in block.items" :key="item">{{ item }}</li></ul><p v-else>{{ block.text }}</p></template></div>
        <section class="reader-connections">
          <header><div><span>Связи материала</span><h2>Продолжить по теме</h2></div><p>Связывай записи в один маршрут обучения. Добавленная связь появится и на графе.</p></header>
          <div v-if="related.length" class="connection-group"><strong>Уже связаны</strong><div class="connection-grid"><button v-for="item in related" :key="item.id" class="connection-card is-linked" type="button" @click="$emit('select',item.id)"><span><UiIcon name="link"/></span><div><b>{{ item.title }}</b><small>{{ item.section }}</small></div><UiIcon name="right"/></button></div></div>
          <div v-if="suggestions.length" class="connection-group"><strong>Можно связать</strong><div class="connection-grid"><article v-for="item in suggestions" :key="item.id" class="connection-card"><button class="connection-card__open" type="button" @click="$emit('select',item.id)"><span><UiIcon name="book"/></span><div><b>{{ item.title }}</b><small>{{ suggestionReason(item) }}</small></div></button><button class="connection-card__add" type="button" :aria-label="`Связать с ${item.title}`" @click="$emit('connect',item.id)"><UiIcon name="plus"/> Связать</button></article></div></div>
          <div v-if="!related.length&&!suggestions.length" class="connections-empty"><UiIcon name="link"/><div><strong>Пока нет подходящих связей</strong><p>Добавь ещё материалы или общие метки — здесь появятся рекомендации.</p></div></div>
        </section>
        <footer class="reader-completion" :class="{completed}"><span><UiIcon :name="completed?'check-circle':'target'"/></span><div><strong>{{ completed?'Материал освоен':'Закончил изучение?' }}</strong><p>{{ completed?'Прогресс сохранён. Можно вернуться позже.':'Отметь материал, чтобы видеть прогресс обучения.' }}</p></div><UiButton :variant="completed?'secondary':'primary'" :icon="completed?'refresh':'check'" @click="$emit('toggle-completed')">{{ completed?'Вернуть в изучение':'Отметить освоенным' }}</UiButton></footer>
      </div>
    </div>
  </article>
  <div v-else class="reader-empty"><span><UiIcon name="book"/></span><strong>Выбери материал</strong><p>Он откроется здесь в спокойном режиме чтения.</p></div>
</template>

<script setup>
import {computed,nextTick,ref,watch} from 'vue';import UiButton from '../../../components/ui/UiButton.vue';import UiIcon from '../../../components/ui/UiIcon.vue';import UiIconButton from '../../../components/ui/UiIconButton.vue';import {estimateReadingMinutes} from '../composables/useKnowledgeBase.js'
const props=defineProps({note:{type:Object,default:null},related:{type:Array,default:()=>[]},suggestions:{type:Array,default:()=>[]},completed:{type:Boolean,default:false}});defineEmits(['show-overview','edit','delete','toggle-pinned','toggle-completed','search-tag','select','connect']);const scrollElement=ref(null);const scrollProgress=ref(0);const readingMinutes=computed(()=>estimateReadingMinutes(props.note?.content));const contentBlocks=computed(()=>parseContent(props.note?.content));const headings=computed(()=>contentBlocks.value.map((block,index)=>({...block,index})).filter(block=>block.type==='heading'))
function parseContent(content){const lines=String(content||'').split('\n');const blocks=[];let list=[];const flush=()=>{if(list.length){blocks.push({type:'list',items:list});list=[]}};lines.forEach(raw=>{const line=raw.trim();if(/^[-*] /.test(line)){list.push(clean(line.slice(2)));return}flush();if(!line)return;if(/^#{1,3} /.test(line))blocks.push({type:'heading',text:clean(line.replace(/^#{1,3} /,''))});else if(line.startsWith('> '))blocks.push({type:'quote',text:clean(line.slice(2))});else blocks.push({type:'paragraph',text:clean(line)})});flush();return blocks}function clean(value){return value.replace(/\[\[([^\]]+)\]\]/g,'$1').replace(/\*\*|__|`/g,'')}function formatDate(value){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date(value))}function suggestionReason(item){if(item.section===props.note?.section)return `Тот же раздел · ${item.section}`;const shared=(item.tags||[]).filter(tag=>(props.note?.tags||[]).includes(tag));return shared.length?`Общая метка · #${shared[0]}`:item.section}function updateScrollProgress(event){const element=event.currentTarget;const available=element.scrollHeight-element.clientHeight;scrollProgress.value=available>0?Math.round(element.scrollTop/available*100):0}function scrollToHeading(index){scrollElement.value?.querySelector(`[data-heading-index="${index}"]`)?.scrollIntoView({behavior:'smooth',block:'start'})}watch(()=>props.note?.id,async()=>{scrollProgress.value=0;await nextTick();scrollElement.value?.scrollTo({top:0})})
</script>

