here}.reader-content h2{scroll-margin-top:22px;margin:16px 0 -2px;font-size:20px;line-height:1.3}.reader-content p{margin:0;white-space:pre-wrap}.reader-content ul{display:grid;gap:5px;margin:0;padding-left:21px}.reader-content li::marker{color:var(--accent)}.reader-content blockquote{margin:3px 0;border-left:3px solid var(--accent);border-radius:0 10px 10px 0;padding:11px 14px;color:var(--text-secondary);background:var(--accent-soft)}.reader-completion{display:grid;grid-template-columns:40px minmax(0,1fr) auto;align-items:center;gap:11px;border:1px solid var(--accent-border);border-radius:15px;padding:13px;background:var(--accent-soft)}.reader-completion>span{width:40px;height:40px;display:grid;place-items:center;border-radius:12px;color:var(--accent);background:var(--card-solid);font-size:18px}.reader-completion strong{font-size:11px}.reader-completion p{margin:2px 0 0;color:var(--text-muted);font-size:8px}.reader-completion.completed{border-color:color-mix(in srgb,var(--success) 35%,var(--border-color));background:color-mix(in srgb,var(--success) 8%,var(--card-soft))}.reader-context{position:sticky;top:0;align-self:start;display:grid;align-content:start;gap:18px;max-height:100%;border-left:1px solid var(--border-color);padding:22px 12px;background:var(--card-soft);overflow-y:auto}.reader-context section{display:grid;gap:4px}.reader-context section>span{margin-bottom:5px;color:var(--text-muted);font-size:8px;font-weight:850;letter-spacing:.08em;text-transform:uppercase}.reader-context section>button{border:0;border-radius:8px;padding:6px 7px;color:var(--text-secondary);background:transparent;font-size:9px;text-align:left}.reader-context section>button:hover{color:var(--accent);background:var(--accent-soft)}.reader-context .related-note{display:grid;grid-template-columns:16px 1fr;gap:6px}.related-note strong,.related-note small{display:block}.related-note small{margin-top:2px;color:var(--text-muted);font-size:8px}.reader-context p{margin:0;color:var(--text-muted);font-size:8px;line-height:1.5}.reader-empty{display:grid;place-items:center;align-content:center;gap:7px;padding:30px;color:var(--text-muted);background:var(--card-solid);text-align:center}.reader-empty>span{width:54px;height:54px;display:grid;place-items:center;border-radius:16px;color:var(--accent);background:var(--accent-soft);font-size:24px}.reader-empty p{margin:0}@media(max-width:1100px){.reader-layout{grid-template-columns:1fr}.reader-context{display:none}}@media(max-width:650px){.reader-document{padding:24px 16px}.reader-completion{grid-template-columns:40px 1fr}.reader-completion :deep(.ui-button){grid-column:1/-1}.breadcrumbs{display:none}.reader-top{justify-content:flex-end}}
