.reader-layout{grid-template-columns:minmax(0,1fr);background:var(--card-solid)}.reader-document{max-width:980px}.reader-outline{display:flex;align-items:center;gap:5px;margin-top:14px;overflow-x:auto;scrollbar-width:none}.reader-outline::-webkit-scrollbar{display:none}.reader-outline>span{flex:0 0 auto;margin-right:2px;color:var(--text-muted);font-size:8px;font-weight:850;letter-spacing:.08em;text-transform:uppercase}.reader-outline button{flex:0 0 auto;border:1px solid var(--border-color);border-radius:99px;padding:5px 8px;color:var(--text-secondary);background:var(--card-soft);font-size:8px}.reader-outline button:hover{border-color:var(--accent-border);color:var(--accent);background:var(--accent-soft)}.reader-connections{display:grid;gap:17px;margin:0 0 18px;border-top:1px solid var(--border-color);padding:24px 0}.reader-connections>header{display:flex;align-items:end;justify-content:space-between;gap:24px}.reader-connections>header span,.connection-group>strong{display:block;color:var(--accent);font-size:8px;font-weight:850;letter-spacing:.09em;text-transform:uppercase}.reader-connections>header h2{margin:4px 0 0;font-size:18px}.reader-connections>header p{max-width:360px;margin:0;color:var(--text-muted);font-size:9px;line-height:1.5}.connection-group{display:grid;gap:8px}.connection-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.connection-card{min-width:0;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;border:1px solid var(--border-color);border-radius:12px;padding:5px;background:var(--card-soft);transition:border-color .16s ease,background .16s ease}.connection-card:hover{border-color:var(--accent-border);background:var(--accent-soft)}button.connection-card{grid-template-columns:30px minmax(0,1fr) 14px;gap:8px;width:100%;padding:9px;color:var(--text-primary);text-align:left}.connection-card>span,.connection-card__open>span{width:30px;height:30px;display:grid;place-items:center;border-radius:9px;color:var(--accent);background:var(--card-solid)}.connection-card b,.connection-card small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.connection-card b{color:var(--text-primary);font-size:10px}.connection-card small{margin-top:2px;color:var(--text-muted);font-size:8px}.connection-card__open{min-width:0;display:grid;grid-template-columns:30px minmax(0,1fr);align-items:center;gap:8px;border:0;padding:4px;color:var(--text-primary);background:transparent;text-align:left}.connection-card__add{display:flex;align-items:center;gap:4px;border:0;border-radius:8px;padding:7px 8px;color:var(--accent);background:var(--card-solid);font-size:8px;font-weight:750}.connection-card__add:hover{background:var(--accent);color:var(--accent-contrast,#fff)}.connections-empty{display:flex;align-items:center;gap:10px;border:1px dashed var(--border-color);border-radius:12px;padding:14px;color:var(--text-muted);background:var(--card-soft)}.connections-empty>svg{font-size:18px}.connections-empty strong{color:var(--text-secondary);font-size:10px}.connections-empty p{margin:2px 0 0;font-size:8px}@media(max-width:700px){.reader-connections>header{align-items:start;flex-direction:column;gap:6px}.connection-grid{grid-template-columns:1fr}}
